sets={}
for filename in ['hallmark.gmt','curated_cgp.gmt']:
 for line in (A/'resources'/filename).read_text().splitlines():
  z=line.split('\t');sets[z[0]]=sorted({canon(g) for g in z[2:] if canon(g)})
