 signatures[layer+'_'+cl]={'up':sorted(set(t.loc[t.mean_delta.gt(0),'canonical_symbol'])),'down':sorted(set(t.loc[t.mean_delta.lt(0),'canonical_symbol'])),'discovery_source':'SCPCP000017','gate':'raw patient P<0.05; fixed deterministic feature per approved symbol before P'}
